import type { Lang } from './types';

/** Every language the app speaks. `ai` is how Gemini is told to write; `bcp` drives speech in and out. */
export const LANGS: { code: Lang; native: string; english: string; bcp: string; ai: string; font?: string }[] = [
  { code: 'en', native: 'English', english: 'English', bcp: 'en-IN', ai: 'simple Indian English' },
  { code: 'hi', native: 'हिन्दी', english: 'Hindi', bcp: 'hi-IN', ai: 'simple Hindi in Devanagari script', font: 'Noto Sans Devanagari' },
  { code: 'hinglish', native: 'Hinglish', english: 'Hinglish', bcp: 'hi-IN', ai: 'simple Hinglish (Hindi written in Roman script)' },
  { code: 'bn', native: 'বাংলা', english: 'Bengali', bcp: 'bn-IN', ai: 'simple Bengali in Bengali script', font: 'Noto Sans Bengali' },
  { code: 'te', native: 'తెలుగు', english: 'Telugu', bcp: 'te-IN', ai: 'simple Telugu in Telugu script', font: 'Noto Sans Telugu' },
  { code: 'mr', native: 'मराठी', english: 'Marathi', bcp: 'mr-IN', ai: 'simple Marathi in Devanagari script', font: 'Noto Sans Devanagari' },
  { code: 'ta', native: 'தமிழ்', english: 'Tamil', bcp: 'ta-IN', ai: 'simple Tamil in Tamil script', font: 'Noto Sans Tamil' },
  { code: 'gu', native: 'ગુજરાતી', english: 'Gujarati', bcp: 'gu-IN', ai: 'simple Gujarati in Gujarati script', font: 'Noto Sans Gujarati' },
  { code: 'kn', native: 'ಕನ್ನಡ', english: 'Kannada', bcp: 'kn-IN', ai: 'simple Kannada in Kannada script', font: 'Noto Sans Kannada' },
  { code: 'ml', native: 'മലയാളം', english: 'Malayalam', bcp: 'ml-IN', ai: 'simple Malayalam in Malayalam script', font: 'Noto Sans Malayalam' },
  { code: 'pa', native: 'ਪੰਜਾਬੀ', english: 'Punjabi', bcp: 'pa-IN', ai: 'simple Punjabi in Gurmukhi script', font: 'Noto Sans Gurmukhi' },
  { code: 'or', native: 'ଓଡ଼ିଆ', english: 'Odia', bcp: 'or-IN', ai: 'simple Odia in Odia script', font: 'Noto Sans Oriya' },
];

export const langInfo = (code: Lang) => LANGS.find((l) => l.code === code) ?? LANGS[0];

/** Fills {name} placeholders. */
export const tf = (s: string, vars: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));

