const PARTIAL: Record<Lang, Partial<Strings>> = { en, hi, hinglish, bn, te, mr, ta, gu, kn, ml, pa, or };

/** Untranslated keys fall back to English, so a missing string never shows as blank. */
export const strings = Object.fromEntries(Object.entries(PARTIAL).map(([k, v]) => [k, { ...en, ...v }])) as Record<Lang, Strings>;

export const VOICE_LANGS = LANGS.filter((l) => l.code !== 'hinglish').map((l) => ({ code: l.bcp, label: `${l.native} · ${l.english}` }));

/** Loads the Noto font for an Indic script the first time that language is chosen. */
export function ensureFont(code: Lang) {
  const font = langInfo(code).font;
  if (!font || typeof document === 'undefined') return;
  const id = `font-${font.replace(/\s+/g, '-')}`;
  if (document.getElementById(id)) return;
  const link = document.createElement('link');
  link.id = id;
  link.rel = 'stylesheet';
  link.href = `https://fonts.googleapis.com/css2?family=${font.replace(/\s+/g, '+')}:wght@400;500;600;700;800&display=swap`;
  document.head.appendChild(link);
}
